/* Motor de la demo local: parejas, turnos, vira, pardas y cantos. */
(function(root){
'use strict';
const SUITS=['Oros','Copas','Espadas','Bastos'];
const DECK=SUITS.flatMap(s=>[1,2,3,4,5,6,7,10,11,12].map(n=>({n,s})));
const team=p=>p%2;
function piece(c,v){if(c.s!==v.s)return 0;if(c.n===(v.n===11?12:11))return 2;if(c.n===(v.n===10?12:10))return 1;return 0}
function power(c,v){const p=piece(c,v);if(p)return 100+p;if(c.n===1&&c.s==='Espadas')return 99;if(c.n===1&&c.s==='Bastos')return 98;if(c.n===7&&c.s==='Espadas')return 97;if(c.n===7&&c.s==='Oros')return 96;return ({3:90,2:89,1:88,12:87,11:86,10:85,7:84,6:83,5:82,4:81})[c.n]}
const index=c=>c.n>=10?0:c.n;
function envido(hand,v){const p=hand.find(c=>piece(c,v));if(p)return (piece(p,v)===2?30:29)+Math.max(...hand.filter(c=>c!==p).map(index));let best=Math.max(...hand.map(index));for(let i=0;i<3;i++)for(let j=i+1;j<3;j++)if(hand[i].s===hand[j].s)best=Math.max(best,20+index(hand[i])+index(hand[j]));return best}
function flor(hand,v){const ps=hand.filter(c=>piece(c,v));if(ps.length===2)return 100;if(ps.length===1){const rest=hand.filter(c=>c!==ps[0]);if(rest[0].s===rest[1].s)return (piece(ps[0],v)===2?30:29)+rest.reduce((a,c)=>a+index(c),0)}if(hand.every(c=>c.s===hand[0].s))return 20+hand.reduce((a,c)=>a+index(c),0);return 0}
function handWinner(results,manoTeam){if(results.length<2)return null;const [a,b,c]=results;if(a!==null&&(b===a||b===null))return a;if(a===null&&b!==null)return b;if(results.length<3)return null;if(c!==null)return c;return a!==null?a:b!==null?b:manoTeam}
class Match{
 constructor({count=4,rng=Math.random}={}){this.count=count;this.rng=rng;this.scores=[0,0];this.mano=0;this.handNo=0;this.matchWinner=null;this.history=[];this.nextHand()}
 log(text){this.message=text;this.history.push(text);this.history=this.history.slice(-40)}
 order(start=this.mano){return Array.from({length:this.count},(_,i)=>(start+i)%this.count)}
 nextHand(){if(this.matchWinner!==null)return false;if(this.handNo)this.mano=(this.mano+1)%this.count;this.handNo++;const d=DECK.map(c=>({...c}));for(let i=d.length-1;i>0;i--){const j=Math.floor(this.rng()*(i+1));[d[i],d[j]]=[d[j],d[i]]}this.hands=Array.from({length:this.count},()=>[]);for(let i=0;i<3;i++)for(const p of this.order())this.hands[p].push(d.pop());this.original=this.hands.map(h=>h.slice());this.vira=d.pop();this.played=Array.from({length:this.count},()=>[]);this.baza=[];this.results=[];this.turn=this.mano;this.leader=this.mano;this.phase='playing';this.pending=null;this.trucoValue=1;this.lastTrucoTeam=null;this.envidoDone=false;this.envidoAward=null;this.florDone=false;this.handResult=null;this.log('Mano '+this.handNo+': abre '+this.name(this.mano)+'.');return true}
 name(p){return this.count===2?['Tú','Rival'][p]:['Tú','Rival izquierdo','Tu compañero','Rival derecho'][p]}
 canPlay(p){return this.phase==='playing'&&!this.pending&&this.turn===p}
 canEnvido(p){return this.canPlay(p)&&!this.envidoDone&&!this.played[p].length&&!this.original.some(h=>flor(h,this.vira))}
 nextTruco(){return ({1:3,3:6,6:9,9:24})[this.trucoValue]||null}
 canTruco(p){return this.canPlay(p)&&this.nextTruco()!==null&&this.lastTrucoTeam!==team(p)}
 opponent(p){return (p+1)%this.count}
 call(p,type,extra=2){if(type==='envido'){if(!this.canEnvido(p))return false;this.envidoDone=true;this.pending={kind:type,from:p,responder:this.opponent(p),amount:2,decline:1};this.log(this.name(p)+' canta Envido.')}else if(type==='truco'){if(!this.canTruco(p))return false;this.pending={kind:type,from:p,responder:this.opponent(p),amount:this.nextTruco(),decline:this.trucoValue};this.log(this.name(p)+' canta '+this.callName(this.nextTruco())+'.')}else return false;return true}
 callName(value){return ({3:'Truco',6:'Retruco',9:'Vale 9',24:'Vale juego'})[value]||'Truco'}
 respond(p,choice,extra=2){const q=this.pending;if(!q||q.responder!==p||this.phase!=='playing')return false;if(choice==='raise'){if(q.kind==='truco'){const n=({3:6,6:9,9:24})[q.amount];if(!n)return false;this.trucoValue=q.amount;this.lastTrucoTeam=team(q.from);q.decline=q.amount;q.amount=n;}else{if(!Number.isInteger(extra)||extra<1||extra>24)return false;q.decline=q.amount;q.amount+=extra;}const prev=q.from;q.from=p;q.responder=prev;this.log(this.name(p)+' sube a '+(q.kind==='envido'?q.amount+' de envite':this.callName(q.amount))+'.');return true}
 this.pending=null;
 if(choice==='no'){if(q.kind==='truco')this.endHand(team(q.from),q.decline,'No quiso '+this.callName(q.amount));else{this.envidoAward={team:team(q.from),points:q.decline,text:'Envite no querido'};this.log(this.name(p)+' no quiere el envite.');}return true}
 if(choice!=='yes'){this.pending=q;return false}
 if(q.kind==='truco'){this.trucoValue=q.amount;this.lastTrucoTeam=team(q.from);this.log(this.name(p)+' quiere '+this.callName(q.amount)+'.');}
 else{let winner=this.mano,best=-1;for(const who of this.order()){const n=envido(this.original[who],this.vira);if(n>best){best=n;winner=who}}this.envidoAward={team:team(winner),points:q.amount,text:'Envite: '+this.name(winner)+' tiene '+best};this.log('Envite querido por '+q.amount+'; se anota al cerrar la mano.');}return true}
 announceFlor(){if(this.florDone)return;this.florDone=true;const entries=this.order().map(p=>({p,value:flor(this.original[p],this.vira)})).filter(x=>x.value);if(!entries.length)return;this.envidoDone=true;this.envidoAward=null;const teams=new Set(entries.map(x=>team(x.p)));if(teams.size===1){const t=team(entries[0].p);this.scores[t]+=3*entries.length;this.log(entries.map(x=>this.name(x.p)).join(' y ')+' canta flor: '+3*entries.length+' tantos.');}else{const best=entries.reduce((a,b)=>b.value>a.value?b:a);this.scores[team(best.p)]+=3;this.log('Flores comparadas sin subida: gana '+this.name(best.p)+' (3 tantos).');}this.checkMatch()}
 checkMatch(){const t=this.scores.findIndex(s=>s>=24);if(t<0)return false;this.matchWinner=t;this.phase='match-over';this.pending=null;return true}
 play(p,slot){if(!this.canPlay(p)||!Number.isInteger(slot)||!this.hands[p][slot])return false;this.announceFlor();if(this.matchWinner!==null)return true;const c=this.hands[p][slot];this.hands[p][slot]=null;this.played[p].push(c);this.baza.push({p,c});this.log(this.name(p)+' juega '+c.n+' de '+c.s+'.');if(this.baza.length===this.count){this.phase='baza-over';return true}this.turn=(p+1)%this.count;return true}
 resolveBaza(){if(this.phase!=='baza-over')return false;const best=Math.max(...this.baza.map(x=>power(x.c,this.vira)));const top=this.baza.filter(x=>power(x.c,this.vira)===best);const tied=new Set(top.map(x=>team(x.p))).size>1;const winner=tied?null:team(top[0].p);this.results.push(winner);this.leader=top[0].p;this.log('Baza '+this.results.length+': '+(tied?'parda.':this.name(top[0].p)+' gana.'));const result=handWinner(this.results,team(this.mano));if(result!==null){this.endHand(result,this.trucoValue,'Mano decidida');return true}this.baza=[];this.turn=this.leader;this.phase='playing';return true}
 endHand(winner,points,reason){if(this.envidoAward){this.scores[this.envidoAward.team]+=this.envidoAward.points;if(this.checkMatch()){this.handResult=this.envidoAward.text;this.log(this.handResult);return}}this.scores[winner]+=points;this.pending=null;this.phase='hand-over';this.handResult=reason+': '+(winner===0?'tu equipo':'rivales')+' suma '+points+'.';this.log(this.handResult);this.checkMatch()}
 botAction(){if(this.phase!=='playing')return false;if(this.pending){const q=this.pending;if(q.responder===0)return false;const strength=q.kind==='envido'?envido(this.original[q.responder],this.vira):Math.max(...this.hands[q.responder].filter(Boolean).map(c=>power(c,this.vira)));return this.respond(q.responder,strength>=(q.kind==='envido'?23:87)?'yes':'no')}
 const p=this.turn;if(p===0)return false;if(this.canEnvido(p)&&envido(this.original[p],this.vira)>=29&&this.rng()<.35)return this.call(p,'envido');if(this.canTruco(p)&&Math.max(...this.hands[p].filter(Boolean).map(c=>power(c,this.vira)))>=98&&this.rng()<.2)return this.call(p,'truco');const available=this.hands[p].map((c,i)=>({c,i})).filter(x=>x.c);available.sort((a,b)=>power(a.c,this.vira)-power(b.c,this.vira));const best=this.baza.length?Math.max(...this.baza.map(x=>power(x.c,this.vira))):0;const highest=this.baza.filter(x=>power(x.c,this.vira)===best);const partnerWinning=highest.length&&highest.every(x=>team(x.p)===team(p));const pick=partnerWinning?available[0]:available.find(x=>power(x.c,this.vira)>best)||available[0];return this.play(p,pick.i)}
}
const api={Match,DECK,power,piece,envido,flor,handWinner,team};if(typeof module!=='undefined')module.exports=api;root.TrucoEngine=api;
})(typeof window==='undefined'?globalThis:window);
